-- C-04: immutable purchase receipts, source-line identity and invoice binding.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema purchase_receipt_private;
revoke all on schema purchase_receipt_private from public,anon,authenticated,service_role;
grant usage on schema purchase_receipt_private to authenticated;
alter table public.purchase_document_line add column source_line_id bigint references public.purchase_document_line(line_id) on delete restrict;
alter table public.stock_movements add column purchase_receipt_line_id bigint references public.purchase_document_line(line_id) on delete restrict;
create unique index stock_purchase_receipt_line_unique on public.stock_movements(purchase_receipt_line_id) where purchase_receipt_line_id is not null;
create index purchase_receipt_source_line_idx on public.purchase_document_line(source_line_id) where source_line_id is not null;
create table purchase_receipt_private.operations(user_id bigint,subsidiary_id bigint,operation_id uuid,fingerprint text not null,document_id bigint not null references public.purchase_document,result jsonb not null,primary key(user_id,subsidiary_id,operation_id));
alter table purchase_receipt_private.operations enable row level security;
revoke all on all tables in schema purchase_receipt_private from public,anon,authenticated,service_role;
create function purchase_receipt_private.replay(p jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=purchase_order_private.access('RECEIPT','create');op uuid;v purchase_receipt_private.operations;begin
 op:=nullif(p->>'operationId','')::uuid;if op is null then raise exception using errcode='22023',message='La recepcion requiere un identificador de operacion.';end if;
 perform pg_advisory_xact_lock(hashtextextended('receipt:'||sid||':'||public.app_user_id()||':'||op,0));
 select * into v from purchase_receipt_private.operations where user_id=public.app_user_id() and subsidiary_id=sid and operation_id=op;
 if v.operation_id is not null then if v.fingerprint<>encode(sha256(convert_to(p::text,'UTF8')),'hex') then raise exception using errcode='55000',message='El reintento contiene datos diferentes.';end if;return v.result;end if;return null;end$$;
create function purchase_receipt_private.origin(id bigint) returns public.purchase_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;sid bigint:=asset_posting_private.identity();begin
 select * into d from public.purchase_document where document_id=id and subsidiary_id=sid and document_type='ORDER' for update;
 if d.document_id is null or d.status<>'APROBADO' then raise exception using errcode='55000',message='La recepcion requiere una orden aprobada de la subsidiaria activa.';end if;return d;end$$;
alter function purchase_order_private.prepare(jsonb,bigint) rename to prepare_before_receipt;
create function purchase_order_private.prepare(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare o public.purchase_document;l jsonb;s public.purchase_document_line;pending numeric;seen bigint[]:='{}';begin
 if p->>'type'<>'RECEIPT' then return purchase_order_private.prepare_before_receipt(p,id);end if;
 perform purchase_order_private.access('RECEIPT',case when id is null then 'create' else 'edit' end);
 if id is not null then raise exception using errcode='55000',message='Una recepcion registrada conserva su historial; no puede editarse.';end if;
 perform purchase_receipt_private.replay(p);o:=purchase_receipt_private.origin(nullif(p->>'source_id','')::bigint);
 if (p->>'supplier_id')::bigint is distinct from o.supplier_id or (p->>'currency_id')::bigint is distinct from o.currency_id or (p->>'rate')::numeric is distinct from o.exchange_rate or (p->>'date')::date<o.document_date or coalesce(p->>'status','RECIBIDO')<>'RECIBIDO' then raise exception using errcode='42501',message='La cabecera debe corresponder a la orden aprobada.';end if;
 p:=purchase_order_private.prepare_before_receipt(p,null);
 for l in select value from jsonb_array_elements(p->'lines') loop
  select * into s from public.purchase_document_line where line_id=nullif(l->>'source_line_id','')::bigint and document_id=o.document_id;
  if s.line_id is null or s.line_id=any(seen) or s.product_id is distinct from (l->>'product_id')::bigint or s.account_id is distinct from (l->>'account_id')::bigint or s.unit_cost is distinct from (l->>'unit_cost')::numeric or s.tax_code_id is distinct from nullif(l->>'tax_code_id','')::bigint or s.tax_rate is distinct from (l->>'tax_rate')::numeric or s.department_id is distinct from nullif(l->>'department_id','')::bigint or s.cost_center_id is distinct from nullif(l->>'cost_center_id','')::bigint or s.class_id is distinct from nullif(l->>'class_id','')::bigint then raise exception using errcode='42501',message='Linea origen incompatible o duplicada.';end if;
  seen:=array_append(seen,s.line_id);
  select s.quantity-coalesce(sum(rl.quantity),0) into pending from public.purchase_document rd join public.purchase_document_line rl on rl.document_id=rd.document_id where rd.document_type='RECEIPT' and rd.source_document_id=o.document_id and rd.status<>'CANCELADO' and (rl.source_line_id=s.line_id or (rl.source_line_id is null and rl.line_number=s.line_number));
  if (l->>'quantity')::numeric>pending then raise exception using errcode='55000',message='La cantidad supera el saldo pendiente de la linea origen.';end if;
 end loop;return p;
end$$;
-- Preserve the writer; attach its newly inserted receipt line to exactly one stock movement.
do $$declare body text;modified text;begin body:=pg_get_functiondef('purchase_order_private.save_purchase_document_without_budget(jsonb,bigint)'::regprocedure);
 modified:=replace(body,'n int:=0;','receipt_line_key bigint;n int:=0;');
 modified:=replace(modified,'related_company_id)values(did,n,','related_company_id,source_line_id)values(did,n,');
 modified:=replace(modified,'nullif(line->>''related_company_id'','''')::bigint);if kind=','nullif(line->>''related_company_id'','''')::bigint,case when kind=''RECEIPT'' then (line->>''source_line_id'')::bigint end)returning line_id into receipt_line_key;if kind=');
 modified:=replace(modified,'quantity,movement_type,unit_cost)values(','quantity,movement_type,unit_cost,purchase_receipt_line_id)values(');
 modified:=replace(modified,'''RECEPCION_COMPRA'',(line->>''unit_cost'')::numeric);','''RECEPCION_COMPRA'',(line->>''unit_cost'')::numeric,receipt_line_key);');
 if modified=body or position('returning line_id into receipt_line_key' in modified)=0 or position('numeric,receipt_line_key)' in modified)=0 then raise exception 'Unexpected purchase writer';end if;execute modified;end$$;
alter function purchase_order_private.engine(jsonb,bigint) rename to engine_before_receipt;
create function purchase_order_private.engine(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;d public.purchase_document;begin
 if p->>'type'<>'RECEIPT' then return purchase_order_private.engine_before_receipt(p,id);end if;
 r:=purchase_receipt_private.replay(p);if r is not null then return r;end if;perform purchase_order_private.prepare(p,id);
 perform set_config('nexo.receipt_write','true',true);r:=purchase_order_private.engine_before_receipt(p,id);perform set_config('nexo.receipt_write','',true);
 select * into d from public.purchase_document where document_id=(r->>'id')::bigint;
 if (select count(*) from public.stock_movements where transaction_id=d.transaction_id)<>(select count(*) from public.purchase_document_line where document_id=d.document_id) then raise exception using errcode='55000',message='La recepcion no produjo movimientos coherentes.';end if;
 insert into purchase_receipt_private.operations values(public.app_user_id(),d.subsidiary_id,(p->>'operationId')::uuid,encode(sha256(convert_to(p::text,'UTF8')),'hex'),d.document_id,r);return r;
end$$;
do $$declare body text;begin body:=pg_get_functiondef('public.budget_run(text,jsonb,bigint)'::regprocedure);if position('declare request_payload jsonb;' in body)=0 then raise exception 'Unexpected budget dispatcher';end if;
 body:=replace(body,'declare request_payload jsonb;','declare receipt_replay jsonb;request_payload jsonb;');
 body:=replace(body,'begin'||chr(10),'begin'||chr(10)||' if p_type=''ORD_COM'' and p_payload->>''type''=''RECEIPT'' and p_id is null then perform pg_advisory_xact_lock(hashtextextended(''budget:''||asset_posting_private.identity(),0));receipt_replay:=purchase_receipt_private.replay(p_payload);if receipt_replay is not null then return receipt_replay;end if;end if;'||chr(10));
 body:=replace(body,'return result||jsonb_build_object(''budgetWarnings'',violations);','if p_type=''ORD_COM'' and p_payload->>''type''=''RECEIPT'' then receipt_replay:=result||jsonb_build_object(''budgetWarnings'',violations);update purchase_receipt_private.operations set result=receipt_replay where user_id=public.app_user_id() and subsidiary_id=sid and operation_id=(p_payload->>''operationId'')::uuid;end if;return result||jsonb_build_object(''budgetWarnings'',violations);');execute body;end$$;
create or replace function public.validate_purchase_receipt_quantity() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;o public.purchase_document;s public.purchase_document_line;used numeric;begin
 select * into d from public.purchase_document where document_id=new.document_id;if d.document_type<>'RECEIPT' then return new;end if;
 o:=purchase_receipt_private.origin(d.source_document_id);
 select * into s from public.purchase_document_line where line_id=new.source_line_id and document_id=o.document_id;
 if s.line_id is null or s.product_id is distinct from new.product_id or s.account_id is distinct from new.account_id then raise exception using errcode='42501',message='La linea no corresponde a la orden aprobada.';end if;
 select coalesce(sum(l.quantity),0) into used from public.purchase_document r join public.purchase_document_line l on l.document_id=r.document_id where r.document_type='RECEIPT' and r.status<>'CANCELADO' and r.source_document_id=o.document_id and l.line_id<>new.line_id and (l.source_line_id=s.line_id or (l.source_line_id is null and l.line_number=s.line_number));
 if not asset_posting_private.finite(new.quantity) or new.quantity<=0 or used+new.quantity>s.quantity then raise exception using errcode='55000',message='La cantidad supera el saldo de la linea origen.';end if;return new;end$$;
create function purchase_receipt_private.stock_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare m public.stock_movements;d public.purchase_document;l public.purchase_document_line;begin
 if tg_op='UPDATE' and (old.purchase_receipt_line_id is not null or old.movement_type='RECEPCION_COMPRA' or exists(select 1 from public.purchase_document where transaction_id=old.transaction_id and document_type='RECEIPT')) then raise exception using errcode='55000',message='El movimiento de recepcion conserva su historial.';end if;
 if tg_op='DELETE' then m:=old;else m:=new;end if;
 select * into d from public.purchase_document where transaction_id=m.transaction_id and document_type='RECEIPT';
 if m.purchase_receipt_line_id is null and m.movement_type<>'RECEPCION_COMPRA' and d.document_id is null then return case when tg_op='DELETE' then old else new end;end if;
 if tg_op<>'INSERT' or current_setting('nexo.receipt_write',true) is distinct from 'true' or d.document_id is null then raise exception using errcode='55000',message='El movimiento de recepcion conserva su historial.';end if;
 select * into l from public.purchase_document_line where line_id=m.purchase_receipt_line_id and document_id=d.document_id;
 if l.line_id is null or m.product_id is distinct from l.product_id or m.location_id is distinct from d.location_id or m.quantity is distinct from l.quantity or m.unit_cost is distinct from l.unit_cost or m.movement_date::date is distinct from d.document_date or m.movement_type<>'RECEPCION_COMPRA' then raise exception using errcode='55000',message='Movimiento de recepcion inconsistente.';end if;return new;end$$;
create trigger receipt_stock_guard before insert or update or delete on public.stock_movements for each row execute function purchase_receipt_private.stock_guard();
create function purchase_receipt_private.document_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;begin
 if tg_table_name='purchase_document' then d:=old;else select * into d from public.purchase_document where document_id=old.document_id;end if;
 if d.document_type='RECEIPT' and exists(select 1 from public.stock_movements where transaction_id=d.transaction_id) then raise exception using errcode='55000',message='La recepcion registrada conserva cantidades, movimientos y vinculos.';end if;return case when tg_op='DELETE' then old else new end;end$$;
create trigger receipt_document_guard before update or delete on public.purchase_document for each row execute function purchase_receipt_private.document_guard();
create trigger receipt_line_guard before update or delete on public.purchase_document_line for each row execute function purchase_receipt_private.document_guard();
-- Source quantities use stable order-line IDs, including conservative fallback for historical receipts.
do $$declare f regprocedure;body text;modified text;begin foreach f in array array['purchase_order_private.purchase_document_detail(bigint)'::regprocedure,'purchase_order_private.purchase_document_report(jsonb)'::regprocedure] loop
 body:=pg_get_functiondef(f);modified:=replace(body,'rl.line_number=l.line_number','(rl.source_line_id=l.line_id or (rl.source_line_id is null and rl.line_number=l.line_number)) and rd.status<>''CANCELADO''');
 modified:=replace(modified,'rl.line_number=ol.line_number','(rl.source_line_id=ol.line_id or (rl.source_line_id is null and rl.line_number=ol.line_number)) and rd.status<>''CANCELADO''');if modified=body then raise exception 'Unexpected source quantities';end if;execute modified;end loop;end$$;
-- Invoice conversion is a bounded read for invoice creators, not a general receipt-view grant.
create function purchase_receipt_private.integrity(id bigint) returns public.purchase_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;o public.purchase_document;begin
 select * into d from public.purchase_document where document_id=id and document_type='RECEIPT' and subsidiary_id=asset_posting_private.identity();
 if d.document_id is null then raise exception using errcode='42501',message='Recepcion no disponible.';end if;o:=purchase_receipt_private.origin(d.source_document_id);
 if d.status not in('RECIBIDO','BORRADOR') or d.currency_id<>o.currency_id or d.supplier_id<>o.supplier_id or d.exchange_rate<>o.exchange_rate or not exists(select 1 from public.purchase_document_line where document_id=id)
 or exists(select 1 from public.purchase_document_line l where l.document_id=id and not exists(select 1 from public.stock_movements m where m.purchase_receipt_line_id=l.line_id and m.transaction_id=d.transaction_id and m.product_id=l.product_id and m.location_id=d.location_id and m.quantity=l.quantity and m.unit_cost=l.unit_cost))
 or (select count(*) from public.stock_movements where transaction_id=d.transaction_id)<>(select count(*) from public.purchase_document_line where document_id=id)
 then raise exception using errcode='55000',message='El origen o los movimientos de la recepcion requieren revision.';end if;return d;end$$;
create function public.supplier_invoice_receipt_source(p_receipt_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;begin
 perform supplier_invoice_private.assert_write(null);d:=purchase_receipt_private.integrity(p_receipt_id);
 if exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=d.document_id) then raise exception using errcode='55000',message='La recepcion ya fue facturada.';end if;
 return purchase_order_private.purchase_document_detail(d.document_id)||jsonb_build_object('accounts',(select coalesce(jsonb_agg(jsonb_build_object('account_id',a.account_id,'account_number',a.account_number,'account_name',a.account_name)),'[]') from public.chart_accounts a where exists(select 1 from public.purchase_document_line l where l.document_id=d.document_id and l.account_id=a.account_id)));end$$;
create function purchase_receipt_private.invoice_binding(p jsonb) returns bigint language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare id bigint:=nullif(p->>'purchase_receipt_document_id','')::bigint;number text:=substring(coalesce(p->>'memo','') from '(REC_INV-[A-Za-z0-9_-]+)');d public.purchase_document;l jsonb;s public.purchase_document_line;n integer:=0;begin
 if id is null and number is not null then select document_id into id from public.purchase_document where document_number=number and document_type='RECEIPT' and subsidiary_id=asset_posting_private.identity();if id is null then raise exception using errcode='42501',message='Recepcion mencionada no disponible.';end if;end if;if id is null then return null;end if;
 d:=purchase_receipt_private.integrity(id);perform 1 from public.purchase_document where document_id=id for update;
 if exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=id) then raise exception using errcode='55000',message='La recepcion ya fue facturada.';end if;
 if number is not null and number<>d.document_number or (p->>'supplier_id')::bigint is distinct from d.supplier_id or (p->>'currency_id')::bigint is distinct from d.currency_id or (p->>'exchange_rate')::numeric is distinct from d.exchange_rate or (p->>'invoice_date')::date<d.document_date or p->>'invoice_type'<>'Factura estándar' then raise exception using errcode='42501',message='Factura incompatible con la recepcion.';end if;
 if jsonb_typeof(p->'lines') is distinct from 'array' then raise exception using errcode='22023',message='Detalle de factura invalido.';end if;
 for l in select value from jsonb_array_elements(p->'lines') loop n:=n+1;select * into s from public.purchase_document_line where document_id=id and line_number=n;
  if s.line_id is null or s.account_id is distinct from (l->>'account_id')::bigint or s.quantity is distinct from (l->>'quantity')::numeric or s.unit_cost is distinct from (l->>'unit_price')::numeric or s.tax_code_id is distinct from nullif(l->>'tax_code_id','')::bigint or s.tax_rate is distinct from coalesce(nullif(l->>'tax_rate','')::numeric,0) or s.department_id is distinct from nullif(l->>'department_id','')::bigint or s.cost_center_id is distinct from nullif(l->>'cost_center_id','')::bigint or s.class_id is distinct from nullif(l->>'class_id','')::bigint then raise exception using errcode='55000',message='Las lineas de factura deben corresponder a la recepcion.';end if;
 end loop;if n<>(select count(*) from public.purchase_document_line where document_id=id) then raise exception using errcode='55000',message='Detalle de recepcion incompleto.';end if;return id;end$$;
alter function supplier_invoice_private.prepare(jsonb,bigint) rename to prepare_before_receipt;
create function supplier_invoice_private.prepare(p jsonb,p_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare id bigint;begin
 p:=supplier_invoice_private.prepare_before_receipt(p,p_id);id:=purchase_receipt_private.invoice_binding(p);if id is not null then p:=p||jsonb_build_object('purchase_receipt_document_id',id);end if;return p;end$$;
create function purchase_receipt_private.invoice_engine(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare rid bigint:=purchase_receipt_private.invoice_binding(p);r jsonb;begin
 perform set_config('nexo.receipt_invoice_id',coalesce(rid::text,''),true);r:=supplier_invoice_private.save_supplier_invoice_without_budget(p,id);perform set_config('nexo.receipt_invoice_id','',true);return r;end$$;
do $$declare body text;modified text;begin body:=pg_get_functiondef('public.budget_run(text,jsonb,bigint)'::regprocedure);modified:=replace(body,'supplier_invoice_private.save_supplier_invoice_without_budget(invoice_payload,p_id)','purchase_receipt_private.invoice_engine(invoice_payload,p_id)');if modified=body then raise exception 'Unexpected invoice dispatcher';end if;execute modified;end$$;
create or replace function public.link_supplier_invoice_to_purchase_receipt() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare rid bigint:=nullif(current_setting('nexo.receipt_invoice_id',true),'')::bigint;begin
 if tg_op='INSERT' and rid is not null then new.purchase_receipt_document_id:=rid;end if;
 if new.purchase_receipt_document_id is not null and not exists(select 1 from public.purchase_document where document_id=new.purchase_receipt_document_id and document_type='RECEIPT' and subsidiary_id=new.subsidiary_id and supplier_id=new.supplier_id and currency_id=new.currency_id) then raise exception using errcode='42501',message='Vinculo de recepcion no autorizado.';end if;return new;end$$;
-- Receipt reads and all write boundaries; shared sales/inventory RPC hardening remains separate.
create function purchase_receipt_private.stock_visible(tid bigint,loc bigint) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin
 return exists(select 1 from public.locations l where l.location_id=loc and (l.subsidiary_id=sid or exists(select 1 from public.location_subsidiaries ls where ls.location_id=l.location_id and ls.subsidiary_id=sid)))
 and (case when tid is null then asset_posting_private.allowed('inventory:stock-movements','view') else exists(select 1 from public."transaction" t where t.transaction_id=tid and t.subsidiary_id=sid and (asset_posting_private.allowed('inventory:stock-movements','view') or (purchase_order_private.allowed('RECEIPT','view') and exists(select 1 from public.purchase_document d where d.transaction_id=tid and d.document_type='RECEIPT')))) end);
 exception when insufficient_privilege then return false;end$$;
create function purchase_receipt_private.legacy_visible(id bigint) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return purchase_order_private.allowed('RECEIPT','view') and exists(select 1 from public.goods_receipt g join public.purchase_order o using(po_id) where g.receipt_id=id and o.subsidiary_id=asset_posting_private.identity());exception when insufficient_privilege then return false;end$$;
do $$declare t text;p record;c record;begin foreach t in array array['stock_movements','goods_receipt'] loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public' and table_name=t loop execute format('revoke all (%I) on public.%I from public,anon,authenticated,service_role',c.column_name,t);end loop;execute format('grant select on public.%I to authenticated',t);
 execute format('create policy receipt_read on public.%I for select to authenticated using(%s)',t,case t when 'stock_movements' then 'purchase_receipt_private.stock_visible(transaction_id,location_id)' else 'purchase_receipt_private.legacy_visible(receipt_id)' end);end loop;end$$;
-- Published row actions follow immutable posting, not the historical BORRADOR label.
alter function purchase_order_private.actions(bigint) rename to actions_before_receipt;
create function purchase_order_private.actions(id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.purchase_document;begin select * into d from public.purchase_document where document_id=id;if d.document_type='RECEIPT' then return jsonb_build_object('canEdit',false,'canDelete',false,'canSubmit',false,'canInvoice',asset_posting_private.allowed('purchasing:supplier-invoices','create') and exists(select 1 from public.purchase_document o where o.document_id=d.source_document_id and o.status='APROBADO') and not exists(select 1 from public.supplier_invoice where purchase_receipt_document_id=d.document_id));end if;return purchase_order_private.actions_before_receipt(id);end$$;
alter function public.purchase_document_access(text) set schema purchase_receipt_private;
create function public.purchase_document_access(p_type text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb:=purchase_receipt_private.purchase_document_access(p_type);begin if p_type='RECEIPT' then r:=r||jsonb_build_object('canCreateNext',asset_posting_private.allowed('purchasing:supplier-invoices','create'));end if;return r;end$$;
